321	     3	module ALU(
322	     4	    input[31:0] A, B,
323	     5	    input[3:0] Control,
324	     6	    output[31:0] res,
325	     7	    output zero, overflow
326	     8	);
327	     9	
328	    10	    parameter ALU_ADD  = 4'b0001;
329	    11	    parameter ALU_SUB  = 4'b0010;
330	    12	    parameter ALU_AND  = 4'b0011;
331	    13	    parameter ALU_OR   = 4'b0100;
332	    14	    parameter ALU_XOR  = 4'b0101;
333	    15	    parameter ALU_SLL  = 4'b0110;
334	    16	    parameter ALU_SRL  = 4'b0111;
335	    17	    parameter ALU_SLT  = 4'b1000;
336	    18	    parameter ALU_SLTU = 4'b1001;
337	    19	    parameter ALU_SRA  = 4'b1010;
338	    20	    parameter ALU_Ap4  = 4'b1011;
339	    21	    parameter ALU_Bout = 4'b1100;
340	    22	
341	    23	    // TODO: implement — compute the ALU result, zero flag, and overflow flag
342	    24	    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
343	    25	    // Use the Control input to select which operation to perform.
344	    26	    // zero should be 1 when res is all zeros.
345	    27	    // overflow should be set for signed ADD/SUB overflow.
346	    28	    assign res = 32'b0;
347	    29	    assign zero = 1'b0;
348	    30	    assign overflow = 1'b0;
