		end 
		else begin
		     if ((Wt_addr != 0) && (L_S == 1)) 	// write
		     register[Wt_addr] <= Wt_data;
		end
	end

    assign Debug_regs = (Debug_addr == 0) ? 0 : register[Debug_addr];               //TEST

